mapper.update:
UPDATE mk_award_intent_outbox
SET status_name = 'SENT', delivery_result = 'CENTER_ACCEPTED',
    attempt_count = attempt_count + 1, benefit_order_no = #{orderNo}, last_error = '',
    lease_owner = NULL, lease_until = NULL, sent_at = #{now}, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND intent_id = #{intentId} AND status_name = 'SENDING'
  AND lease_owner = #{workerId} AND lease_version = #{leaseVersion}

UPDATE mk_award_intent_outbox
SET status_name = #{statusName}, attempt_count = attempt_count + 1,
    next_attempt_at = #{nextAttemptAt}, last_error = #{lastError},
    lease_owner = NULL, lease_until = NULL, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND intent_id = #{intentId} AND status_name = 'SENDING'
  AND lease_owner = #{workerId} AND lease_version = #{leaseVersion}
